//! M0 spike evidence: the placeholder tileset is generated by this repository, the isometric
//! Tiled map loads with its custom tile properties (assumption A2), and the projection of PLAN.md
//! section 5, equation 7, is reconciled with the `bevy_ecs_tilemap` diamond convention.

use std::path::PathBuf;

use bevy_ecs_tiled::prelude::tiled::{Loader, Map, Orientation, PropertyValue, TileLayer};
use bevy_ecs_tiled::prelude::tilemap_type_from_map;
use bevy_ecs_tilemap::prelude::{
    IsoCoordSystem, TilePos, TilemapAnchor, TilemapGridSize, TilemapSize, TilemapTileSize,
    TilemapType,
};

#[path = "../examples/gen_spike_tileset.rs"]
#[allow(dead_code)]
mod gen_spike_tileset;

fn spike_map_path() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../assets/maps/spike/spike.tmx")
}

fn load_spike_map() -> Map {
    Loader::new()
        .load_tmx_map(spike_map_path())
        .expect("spike map loads")
}

// --- Asset provenance -----------------------------------------------------------------------

#[test]
fn committed_tileset_matches_generator_output() {
    let committed = std::fs::read(gen_spike_tileset::output_path()).expect("tileset is committed");
    assert!(
        committed == gen_spike_tileset::tileset_png(),
        "assets/maps/spike/spike_tiles.png differs from the generator; \
         run `cargo run -p game --example gen_spike_tileset`"
    );
}

// --- Assumption A2 --------------------------------------------------------------------------

#[test]
fn spike_map_is_an_isometric_diamond_map() {
    let map = load_spike_map();
    assert_eq!(map.orientation, Orientation::Isometric);
    assert_eq!((map.width, map.height), (16, 16));
    assert_eq!((map.tile_width, map.tile_height), (64, 32));
    assert_eq!(
        tilemap_type_from_map(&map),
        TilemapType::Isometric(IsoCoordSystem::Diamond)
    );
}

#[test]
fn spike_map_exposes_custom_tile_properties() {
    let map = load_spike_map();
    let tileset = &map.tilesets()[0];
    let property = |tile_id: u32, name: &str| {
        tileset
            .get_tile(tile_id)
            .and_then(|tile| tile.properties.get(name).cloned())
    };

    assert_eq!(
        property(0, "terrain"),
        Some(PropertyValue::StringValue("grass".into()))
    );
    assert_eq!(
        property(0, "buildable"),
        Some(PropertyValue::BoolValue(true))
    );
    assert_eq!(
        property(1, "terrain"),
        Some(PropertyValue::StringValue("ore".into()))
    );
    assert_eq!(property(1, "ore"), Some(PropertyValue::IntValue(500)));
    assert_eq!(property(0, "ore"), None);
}

#[test]
fn spike_map_cells_use_tiled_coordinates() {
    let map = load_spike_map();
    let TileLayer::Finite(layer) = map.layers().next().and_then(|l| l.as_tile_layer()).unwrap()
    else {
        panic!("spike map layer is finite");
    };
    let tile_id = |x, y| layer.get_tile(x, y).map(|tile| tile.id());
    assert_eq!(tile_id(0, 0), Some(2), "red origin marker at cell (0, 0)");
    assert_eq!(tile_id(15, 0), Some(3), "blue marker at cell (15, 0)");
    assert_eq!(tile_id(6, 10), Some(1), "ore inside the patch");
    assert_eq!(tile_id(0, 15), Some(0), "grass");
    assert_eq!(tile_id(16, 0), None, "outside the map");
}

// --- Projection reconciliation (PLAN.md section 5, equation 7) ------------------------------

const W: f32 = 64.0;
const H: f32 = 32.0;

/// Equation 7 as written in the plan, for continuous cell coordinates (cell c spans [c, c + 1)).
fn plan_cell_to_world(cx: f32, cy: f32) -> (f32, f32) {
    ((cx - cy) * W / 2.0, -(cx + cy) * H / 2.0)
}

fn plan_world_to_cell(world_x: f32, world_y: f32) -> (i32, i32) {
    let a = world_x / (W / 2.0);
    let b = -world_y / (H / 2.0);
    (
        ((a + b) / 2.0).floor() as i32,
        ((b - a) / 2.0).floor() as i32,
    )
}

/// The reconciled form recorded in docs/DECISIONS.md: `bevy_ecs_tiled` stores Tiled cell
/// (cx, cy) at `TilePos { x: cx, y: height - 1 - cy }`, and with `TilemapAnchor::None` the
/// tilemap places that tile's centre at equation 7 evaluated at the cell centre plus
/// `((height - 1) * W / 2, height * H / 2)`.
fn reconciled_offset(map_height: u32) -> (f32, f32) {
    (
        (map_height as f32 - 1.0) * W / 2.0,
        map_height as f32 * H / 2.0,
    )
}

#[test]
fn plan_projection_matches_bevy_ecs_tilemap_diamond_for_every_cell() {
    let grid = TilemapGridSize { x: W, y: H };
    let tile = TilemapTileSize { x: W, y: H };
    let map_type = TilemapType::Isometric(IsoCoordSystem::Diamond);

    for (width, height) in [(1, 1), (1, 7), (7, 1), (16, 16), (64, 64), (3, 50)] {
        let size = TilemapSize {
            x: width,
            y: height,
        };
        let (off_x, off_y) = reconciled_offset(height);
        for cy in 0..height {
            for cx in 0..width {
                let tile_pos = TilePos {
                    x: cx,
                    y: height - 1 - cy,
                };
                let crate_centre =
                    tile_pos.center_in_world(&size, &grid, &tile, &map_type, &TilemapAnchor::None);

                let (px, py) = plan_cell_to_world(cx as f32 + 0.5, cy as f32 + 0.5);
                let ctx = format!("map {width}x{height}, cell ({cx}, {cy})");
                assert!((px + off_x - crate_centre.x).abs() < 1e-3, "x, {ctx}");
                assert!((py + off_y - crate_centre.y).abs() < 1e-3, "y, {ctx}");

                // The plan's inverse recovers the cell from its centre, and the crate's own
                // picking agrees after the same offset.
                assert_eq!(
                    plan_world_to_cell(px, py),
                    (cx as i32, cy as i32),
                    "inverse, {ctx}"
                );
                let picked = TilePos::from_world_pos(
                    &crate_centre,
                    &size,
                    &grid,
                    &tile,
                    &map_type,
                    &TilemapAnchor::None,
                );
                assert_eq!(picked, Some(tile_pos), "crate picking, {ctx}");
            }
        }
    }
}

#[test]
fn plan_projection_puts_cell_origin_at_top_corner() {
    // Integer cell coordinates are diamond corners: (0, 0) is the top corner of cell (0, 0),
    // +x runs down-right and +y runs down-left on screen (Bevy's y axis points up).
    assert_eq!(plan_cell_to_world(0.0, 0.0), (0.0, 0.0));
    assert_eq!(plan_cell_to_world(1.0, 0.0), (W / 2.0, -H / 2.0));
    assert_eq!(plan_cell_to_world(0.0, 1.0), (-W / 2.0, -H / 2.0));
    // Points just inside the corners of cell (0, 0) pick it; just outside do not.
    assert_eq!(plan_world_to_cell(0.0, -0.01), (0, 0));
    assert_eq!(plan_world_to_cell(0.0, 0.01), (-1, -1));
    assert_eq!(plan_world_to_cell(0.0, -H + 0.01), (0, 0));
    assert_eq!(plan_world_to_cell(0.0, -H - 0.01), (1, 1));
}
